/**
 * Generated by `createservice subscription.CancelSubscriptionRenewalService --type mutations`
 */
const uniq = require('lodash/uniq')

const { GQLError, GQLErrorCode: { BAD_USER_INPUT } } = require('@open-condo/keystone/errors')
const { getLogger } = require('@open-condo/keystone/logging')
const { GQLCustomSchema, find } = require('@open-condo/keystone/schema')

const { NOT_FOUND } = require('@condo/domains/common/constants/errors')
const access = require('@condo/domains/subscription/access/CancelSubscriptionRenewalService')
const { SubscriptionContext } = require('@condo/domains/subscription/utils/serverSchema')
const { deleteUnusedCardTokens } = require('@condo/domains/subscription/utils/serverSchema/deleteUnusedCardTokens')

const logger = getLogger('CancelSubscriptionRenewalService')

/**
 * List of possible errors, that this custom schema can throw
 * They will be rendered in documentation section in GraphiQL for this custom schema
 */
const ERRORS = {
    SUBSCRIPTION_CONTEXT_NOT_FOUND: {
        mutation: 'cancelSubscriptionRenewal',
        variable: ['data', 'subscriptionContexts'],
        code: BAD_USER_INPUT,
        type: NOT_FOUND,
        message: 'SubscriptionContext not found',
    },
    SUBSCRIPTION_CONTEXTS_FROM_DIFFERENT_ORGANIZATIONS: {
        mutation: 'cancelSubscriptionRenewal',
        variable: ['data', 'subscriptionContexts'],
        code: BAD_USER_INPUT,
        type: 'SUBSCRIPTION_CONTEXTS_FROM_DIFFERENT_ORGANIZATIONS',
        message: 'All subscription contexts must belong to the same organization',
    },
}

const CancelSubscriptionRenewalService = new GQLCustomSchema('CancelSubscriptionRenewalService', {
    types: [
        {
            access: true,
            type: 'input CancelSubscriptionRenewalInput { dv: Int!, sender: SenderFieldInput!, subscriptionContexts: [SubscriptionContextWhereUniqueInput!]! }',
        },
        {
            access: true,
            type: 'type CancelSubscriptionRenewalOutput { subscriptionContexts: [SubscriptionContext!]! }',
        },
    ],

    mutations: [
        {
            access: access.canCancelSubscriptionRenewal,
            schema: 'cancelSubscriptionRenewal(data: CancelSubscriptionRenewalInput!): CancelSubscriptionRenewalOutput',
            doc: {
                summary: 'Cancels renewal of exactly the given subscription contexts: detaches the card and records renewalCancelledAt. The paid period stays active.',
                errors: ERRORS,
            },
            resolver: async (parent, args, context) => {
                const { data: { dv, sender, subscriptionContexts: subscriptionContextsInput } } = args

                const subscriptionContextIds = uniq(subscriptionContextsInput.map(({ id }) => id))
                const subscriptionContexts = await find('SubscriptionContext', { id_in: subscriptionContextIds, deletedAt: null })
                if (subscriptionContextIds.length === 0 || subscriptionContexts.length !== subscriptionContextIds.length) {
                    throw new GQLError(ERRORS.SUBSCRIPTION_CONTEXT_NOT_FOUND, context)
                }

                const organizationIds = uniq(subscriptionContexts.map(subscriptionContext => subscriptionContext.organization))
                if (organizationIds.length > 1) {
                    throw new GQLError(ERRORS.SUBSCRIPTION_CONTEXTS_FROM_DIFFERENT_ORGANIZATIONS, context)
                }
                const [organizationId] = organizationIds

                const releasedBindingIds = uniq(subscriptionContexts.map(subscriptionContext => subscriptionContext.bindingId).filter(Boolean))
                const now = new Date().toISOString()

                // The only place renewalCancelledAt is set: it records that the organization declined renewal itself
                for (const subscriptionContext of subscriptionContexts) {
                    await SubscriptionContext.update(context, subscriptionContext.id, {
                        dv,
                        sender,
                        bindingId: null,
                        renewalCancelledAt: subscriptionContext.renewalCancelledAt || now,
                    })
                }
                logger.info({ msg: 'Cancelled subscription renewal', data: { organizationId, subscriptionContextIds } })

                await deleteUnusedCardTokens({ organizationId, bindingIds: releasedBindingIds, detachedContextIds: subscriptionContextIds })

                const updatedSubscriptionContexts = await find('SubscriptionContext', { id_in: subscriptionContextIds, deletedAt: null })
                return { subscriptionContexts: updatedSubscriptionContexts }
            },
        },
    ],

})

module.exports = {
    CancelSubscriptionRenewalService,
    ERRORS,
}
